-- 298: 年間指導計画(0歳児)の月齢区分を全項目で統一(元Excelの段階ズレを修正)。sections差し替え。
update guidance_plan_templates set sections = '[{"key": "goal", "label": "年間の枠", "fields": [{"key": "goal", "label": "年間目標", "required": true, "subject": "子ども"}, {"key": "$健康安全災害$", "label": "健康・安全・災害", "required": false, "subject": "保育者"}]}, {"key": "aim", "label": "ねらい(各期)", "hint": "その期に育てたい姿を、子どもを主語に。", "fields": [{"key": "aim*term1", "label": "1期(4〜6月)", "required": true, "subject": "子ども"}, {"key": "aim*term2", "label": "2期(7〜9月)", "required": true, "subject": "子ども"}, {"key": "aim*term3", "label": "3期(10〜12月)", "required": true, "subject": "子ども"}, {"key": "aim*term4", "label": "4期(1〜3月)", "required": true, "subject": "子ども"}]}, {"key": "schedule", "label": "園行事及び園事業(各期)", "fields": [{"key": "schedule*term1", "label": "1期(4〜6月)", "required": false}, {"key": "schedule*term2", "label": "2期(7〜9月)", "required": false}, {"key": "schedule*term3", "label": "3期(10〜12月)", "required": false}, {"key": "schedule*term4", "label": "4期(1〜3月)", "required": false}]}, {"key": "kidsstate", "label": "子どもの姿", "hint": "前年度/前期や連絡帳・記録から、その月齢の子どもの姿を具体的に。", "fields": [{"key": "kidsstate*$57日〜3ヶ月未満$", "label": "57日〜3ヶ月未満", "required": true, "subject": "子ども"}, {"key": "kidsstate*$3ヶ月〜6ヶ月未満$", "label": "3ヶ月〜6ヶ月未満", "required": true, "subject": "子ども"}, {"key": "kidsstate*$6ヶ月〜9ヶ月未満$", "label": "6ヶ月〜9ヶ月未満", "required": true, "subject": "子ども"}, {"key": "kidsstate*$9ヶ月〜12ヶ月未満$", "label": "9ヶ月〜12ヶ月未満", "required": true, "subject": "子ども"}, {"key": "kidsstate*$1歳〜1歳3ヶ月未満$", "label": "1歳〜1歳3ヶ月未満", "required": true, "subject": "子ども"}, {"key": "kidsstate*$1歳3ヶ月〜2歳未満$", "label": "1歳3ヶ月〜2歳未満", "required": true, "subject": "子ども"}]}, {"key": "nursing", "label": "養護(生命の保持・情緒の安定)", "hint": "保育者を主語に。健康・安全・清潔と情緒の安定。", "fields": [{"key": "nursing*$57日〜3ヶ月未満$", "label": "57日〜3ヶ月未満", "required": true, "subject": "保育者"}, {"key": "nursing*$3ヶ月〜6ヶ月未満$", "label": "3ヶ月〜6ヶ月未満", "required": true, "subject": "保育者"}, {"key": "nursing*$6ヶ月〜9ヶ月未満$", "label": "6ヶ月〜9ヶ月未満", "required": true, "subject": "保育者"}, {"key": "nursing*$9ヶ月〜12ヶ月未満$", "label": "9ヶ月〜12ヶ月未満", "required": true, "subject": "保育者"}, {"key": "nursing*$1歳〜1歳3ヶ月未満$", "label": "1歳〜1歳3ヶ月未満", "required": true, "subject": "保育者"}, {"key": "nursing*$1歳3ヶ月〜2歳未満$", "label": "1歳3ヶ月〜2歳未満", "required": true, "subject": "保育者"}]}, {"key": "education", "label": "教育(3つの視点)", "hint": "健やかに伸び伸びと育つ/身近な人と気持ちが通じ合う/身近なものと関わり感性が育つ。", "fields": [{"key": "education*$57日〜3ヶ月未満$", "label": "57日〜3ヶ月未満", "required": true, "subject": "子ども"}, {"key": "education*$3ヶ月〜6ヶ月未満$", "label": "3ヶ月〜6ヶ月未満", "required": true, "subject": "子ども"}, {"key": "education*$6ヶ月〜9ヶ月未満$", "label": "6ヶ月〜9ヶ月未満", "required": true, "subject": "子ども"}, {"key": "education*$9ヶ月〜12ヶ月未満$", "label": "9ヶ月〜12ヶ月未満", "required": true, "subject": "子ども"}, {"key": "education*$1歳〜1歳3ヶ月未満$", "label": "1歳〜1歳3ヶ月未満", "required": true, "subject": "子ども"}, {"key": "education*$1歳3ヶ月〜2歳未満$", "label": "1歳3ヶ月〜2歳未満", "required": true, "subject": "子ども"}]}, {"key": "aid", "label": "保育者の援助", "hint": "保育者を主語に。育ちを支える関わり。", "fields": [{"key": "aid*$57日〜3ヶ月未満$", "label": "57日〜3ヶ月未満", "required": true, "subject": "保育者"}, {"key": "aid*$3ヶ月〜6ヶ月未満$", "label": "3ヶ月〜6ヶ月未満", "required": true, "subject": "保育者"}, {"key": "aid*$6ヶ月〜9ヶ月未満$", "label": "6ヶ月〜9ヶ月未満", "required": true, "subject": "保育者"}, {"key": "aid*$9ヶ月〜12ヶ月未満$", "label": "9ヶ月〜12ヶ月未満", "required": true, "subject": "保育者"}, {"key": "aid*$1歳〜1歳3ヶ月未満$", "label": "1歳〜1歳3ヶ月未満", "required": true, "subject": "保育者"}, {"key": "aid*$1歳3ヶ月〜2歳未満$", "label": "1歳3ヶ月〜2歳未満", "required": true, "subject": "保育者"}]}, {"key": "withhome", "label": "子育ての支援", "hint": "保護者を主語に含め、家庭との連携・支援。", "fields": [{"key": "withhome*$57日〜3ヶ月未満$", "label": "57日〜3ヶ月未満", "required": true, "subject": "保育者"}, {"key": "withhome*$3ヶ月〜6ヶ月未満$", "label": "3ヶ月〜6ヶ月未満", "required": true, "subject": "保育者"}, {"key": "withhome*$6ヶ月〜9ヶ月未満$", "label": "6ヶ月〜9ヶ月未満", "required": true, "subject": "保育者"}, {"key": "withhome*$9ヶ月〜12ヶ月未満$", "label": "9ヶ月〜12ヶ月未満", "required": true, "subject": "保育者"}, {"key": "withhome*$1歳〜1